package zeabur

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/atoll-sh/atoll/internal/agent"
	"github.com/atoll-sh/atoll/internal/api"
)

// ParkLabel is the nodeSelector key that no node carries; adding it unschedules a DaemonSet.
const ParkLabel = "atoll.sh/parked"

// k3s ServiceLB (klipper-lb) runs "svclb-*" DaemonSets holding hostPorts for LoadBalancer
// Services; they are re-generated by k3s, so they are stopped with this node label instead.
const svclbLabel = "svccontroller.k3s.cattle.io/enablelb"

// DaemonSet is the subset of a DaemonSet we read (kubectl -o json).
type DaemonSet struct {
	Metadata struct {
		Name      string            `json:"name"`
		Namespace string            `json:"namespace"`
		Labels    map[string]string `json:"labels"`
	} `json:"metadata"`
	Spec struct {
		Template struct {
			Spec struct {
				NodeSelector map[string]string `json:"nodeSelector"`
				HostNetwork  bool              `json:"hostNetwork"`
				Containers   []struct {
					Name  string `json:"name"`
					Ports []struct {
						ContainerPort int    `json:"containerPort"`
						HostPort      int    `json:"hostPort"`
						Protocol      string `json:"protocol"`
					} `json:"ports"`
				} `json:"containers"`
			} `json:"spec"`
		} `json:"template"`
	} `json:"spec"`
	Status struct {
		DesiredNumberScheduled int `json:"desiredNumberScheduled"`
		CurrentNumberScheduled int `json:"currentNumberScheduled"`
		NumberReady            int `json:"numberReady"`
	} `json:"status"`
}

func (d DaemonSet) Key() string { return d.Metadata.Namespace + "/" + d.Metadata.Name }

// Running reports whether any pod of the DaemonSet is scheduled.
func (d DaemonSet) Running() bool {
	return d.Status.CurrentNumberScheduled > 0 || d.Status.NumberReady > 0
}

func (d DaemonSet) Parked() bool { return d.Spec.Template.Spec.NodeSelector[ParkLabel] != "" }

func (d DaemonSet) IsSvcLB() bool { return strings.HasPrefix(d.Metadata.Name, "svclb-") }

var ingressNameRe = regexp.MustCompile(`(?i)ingress|traefik|nginx|caddy|envoy|haproxy|gateway`)

// IsIngress reports whether a DaemonSet serves host ports 80/443: an explicit hostPort 80/443,
// or hostNetwork with an ingress-like name.
func (d DaemonSet) IsIngress() bool {
	for _, c := range d.Spec.Template.Spec.Containers {
		for _, p := range c.Ports {
			if p.HostPort == 80 || p.HostPort == 443 {
				return true
			}
			if d.Spec.Template.Spec.HostNetwork && (p.ContainerPort == 80 || p.ContainerPort == 443) {
				return true
			}
		}
	}
	return d.Spec.Template.Spec.HostNetwork && ingressNameRe.MatchString(d.Metadata.Name)
}

// ParseDaemonSets parses `kubectl get ds -A -o json` and returns the ingress ones, sorted.
func ParseDaemonSets(b []byte) ([]DaemonSet, error) {
	var list struct {
		Items []DaemonSet `json:"items"`
	}
	if err := json.Unmarshal(b, &list); err != nil {
		return nil, fmt.Errorf("parse daemonsets: %w", err)
	}
	var out []DaemonSet
	for _, d := range list.Items {
		if d.IsIngress() {
			out = append(out, d)
		}
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Key() < out[j].Key() })
	return out, nil
}

func (t *Takeover) ingressDaemonSets(ctx context.Context) ([]DaemonSet, error) {
	out, err := t.kubectl(ctx, "get", "daemonsets", "-A", "-o", "json")
	if err != nil {
		return nil, err
	}
	return ParseDaemonSets(out)
}

// IngressGuard is registered on the agent's Ingress: atoll-caddy must not bind 80/443 while
// a Zeabur/k3s ingress DaemonSet still has pods (hostPort DNAT would compete for the ports).
func (t *Takeover) IngressGuard(ctx context.Context) error {
	if _, err := t.k3sBin(); err != nil {
		return nil
	}
	if st, err := t.State.Load(); err == nil && st.K3sRemoved {
		return nil
	}
	ds, err := t.ingressDaemonSets(ctx)
	if err != nil {
		// k3s installed but API down: its pods are not serving either; don't block.
		t.Log.Warn("ingress guard: cannot list daemonsets", "err", err)
		return nil
	}
	var running []string
	for _, d := range ds {
		if d.Running() {
			running = append(running, d.Key())
		}
	}
	if len(running) > 0 {
		return fmt.Errorf("Zeabur/k3s ingress is still running (%s); park it first (zeabur.ingress park=true)", strings.Join(running, ", "))
	}
	return nil
}

// ParkIngress unschedules every ingress DaemonSet (recording the original nodeSelector), waits
// for their pods to go, and verifies ports 80/443 are free.
func (t *Takeover) ParkIngress(ctx context.Context) (string, error) {
	st, err := t.State.Load()
	if err != nil {
		return "", err
	}
	if st.K3sRemoved {
		return "k3s already removed; nothing to park", nil
	}
	ds, err := t.ingressDaemonSets(ctx)
	if err != nil {
		return "", err
	}
	var parked []string
	for _, d := range ds {
		if d.IsSvcLB() {
			if err := t.parkSvcLB(ctx); err != nil {
				return "", err
			}
			parked = append(parked, d.Key()+" (servicelb node label)")
			continue
		}
		if d.Parked() {
			parked = append(parked, d.Key()+" (already)")
			continue
		}
		orig := d.Spec.Template.Spec.NodeSelector
		if orig == nil {
			orig = map[string]string{}
		}
		// Record first so a crash between record and patch can still be rolled back.
		if _, err := t.State.Update(func(s *State) error {
			for _, p := range s.ParkedDaemonSets {
				if p.Namespace == d.Metadata.Namespace && p.Name == d.Metadata.Name {
					return nil
				}
			}
			s.ParkedDaemonSets = append(s.ParkedDaemonSets, ParkedDaemonSet{
				Namespace: d.Metadata.Namespace, Name: d.Metadata.Name, OriginalNodeSelector: orig,
			})
			return nil
		}); err != nil {
			return "", err
		}
		patch := fmt.Sprintf(`{"spec":{"template":{"spec":{"nodeSelector":{%q:"true"}}}}}`, ParkLabel)
		if _, err := t.kubectl(ctx, "patch", "daemonset", d.Metadata.Name, "-n", d.Metadata.Namespace, "--type", "merge", "-p", patch); err != nil {
			return "", fmt.Errorf("park %s: %w", d.Key(), err)
		}
		parked = append(parked, d.Key())
	}
	if err := t.waitIngressGone(ctx); err != nil {
		return "", err
	}
	if t.PortsFree != nil {
		if err := t.PortsFree(ctx); err != nil {
			// atoll-caddy may legitimately hold them already (re-park).
			if info, ierr := t.RT.InspectContainer(ctx, agent.CaddyContainer); ierr != nil || info.State != "running" {
				return "", fmt.Errorf("ingress parked but ports still busy: %w", err)
			}
		}
	}
	now := time.Now().UTC()
	if _, err := t.State.Update(func(s *State) error {
		s.IngressParked = true
		s.CutoverAt = &now
		return nil
	}); err != nil {
		return "", err
	}
	return asJSON(map[string]any{"parked": parked})
}

func (t *Takeover) waitIngressGone(ctx context.Context) error {
	deadline := time.Now().Add(t.ParkWait)
	for {
		ds, err := t.ingressDaemonSets(ctx)
		if err != nil {
			return err
		}
		var still []string
		for _, d := range ds {
			if d.Running() {
				still = append(still, d.Key())
			}
		}
		if len(still) == 0 {
			return nil
		}
		if time.Now().After(deadline) {
			return fmt.Errorf("ingress pods still running after %s: %s", t.ParkWait, strings.Join(still, ", "))
		}
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-time.After(t.PollEvery):
		}
	}
}

func (t *Takeover) nodes(ctx context.Context) (map[string]map[string]string, error) {
	out, err := t.kubectl(ctx, "get", "nodes", "-o", "json")
	if err != nil {
		return nil, err
	}
	var list struct {
		Items []struct {
			Metadata struct {
				Name   string            `json:"name"`
				Labels map[string]string `json:"labels"`
			} `json:"metadata"`
		} `json:"items"`
	}
	if err := json.Unmarshal(out, &list); err != nil {
		return nil, err
	}
	m := map[string]map[string]string{}
	for _, n := range list.Items {
		m[n.Metadata.Name] = n.Metadata.Labels
	}
	return m, nil
}

func (t *Takeover) parkSvcLB(ctx context.Context) error {
	nodes, err := t.nodes(ctx)
	if err != nil {
		return err
	}
	for name, labels := range nodes {
		prev, had := labels[svclbLabel]
		if had && prev == "false" {
			continue
		}
		if _, err := t.State.Update(func(s *State) error {
			for _, r := range s.NodeLabels {
				if r.Node == name && r.Key == svclbLabel {
					return nil
				}
			}
			s.NodeLabels = append(s.NodeLabels, NodeLabelRecord{Node: name, Key: svclbLabel, Previous: prev, Had: had})
			return nil
		}); err != nil {
			return err
		}
		if _, err := t.kubectl(ctx, "label", "node", name, svclbLabel+"=false", "--overwrite"); err != nil {
			return err
		}
	}
	return nil
}

// RestoreIngress reverses ParkIngress. atoll-caddy is stopped first so the ports are free.
func (t *Takeover) RestoreIngress(ctx context.Context) (string, error) {
	st, err := t.State.Load()
	if err != nil {
		return "", err
	}
	if st.K3sRemoved {
		return "", errors.New("k3s has been uninstalled; Zeabur ingress cannot be restored (rollback impossible)")
	}
	if err := t.RT.StopContainer(ctx, agent.CaddyContainer, 10*time.Second); err != nil && !errors.Is(err, agent.ErrNotFound) {
		return "", fmt.Errorf("stop %s: %w", agent.CaddyContainer, err)
	}
	var restored []string
	for _, p := range st.ParkedDaemonSets {
		// JSON merge patch: null removes our key and leaves the original selector intact.
		sel := map[string]any{ParkLabel: nil}
		if v, ok := p.OriginalNodeSelector[ParkLabel]; ok {
			sel[ParkLabel] = v
		}
		b, _ := json.Marshal(map[string]any{"spec": map[string]any{"template": map[string]any{"spec": map[string]any{"nodeSelector": sel}}}})
		if _, err := t.kubectl(ctx, "patch", "daemonset", p.Name, "-n", p.Namespace, "--type", "merge", "-p", string(b)); err != nil {
			return "", fmt.Errorf("restore %s/%s: %w", p.Namespace, p.Name, err)
		}
		restored = append(restored, p.Namespace+"/"+p.Name)
	}
	for _, r := range st.NodeLabels {
		arg := r.Key + "-"
		if r.Had {
			arg = r.Key + "=" + r.Previous
		}
		if _, err := t.kubectl(ctx, "label", "node", r.Node, arg, "--overwrite"); err != nil {
			return "", err
		}
		restored = append(restored, "node/"+r.Node+" "+r.Key)
	}
	if _, err := t.State.Update(func(s *State) error {
		s.ParkedDaemonSets, s.NodeLabels = nil, nil
		s.IngressParked, s.CutoverAt = false, nil
		return nil
	}); err != nil {
		return "", err
	}
	return asJSON(map[string]any{"restored": restored})
}

// ---------- scale ----------

var workloadRe = regexp.MustCompile(`^(deployment|statefulset|deploy|sts)/[a-z0-9]([a-z0-9.-]*[a-z0-9])?$`)
var nsRe = regexp.MustCompile(`^[a-z0-9]([a-z0-9-]*[a-z0-9])?$`)

// RestoreReplicas as ZeaburScalePayload.Replicas means "scale back to the recorded original".
const RestoreReplicas = -1

// Scale sets replicas, recording the original count the first time atoll changes a workload.
func (t *Takeover) Scale(ctx context.Context, p api.ZeaburScalePayload) (WorkloadRecord, error) {
	if !nsRe.MatchString(p.Namespace) || !workloadRe.MatchString(p.Workload) {
		return WorkloadRecord{}, fmt.Errorf("invalid namespace/workload %q/%q", p.Namespace, p.Workload)
	}
	st, err := t.State.Load()
	if err != nil {
		return WorkloadRecord{}, err
	}
	if st.K3sRemoved {
		return WorkloadRecord{}, errors.New("k3s has been uninstalled; Zeabur workloads cannot be scaled (rollback impossible)")
	}
	key := p.Namespace + "/" + p.Workload
	rec, known := st.Workloads[key]
	if !known {
		out, err := t.kubectl(ctx, "get", p.Workload, "-n", p.Namespace, "-o", "jsonpath={.spec.replicas}")
		if err != nil {
			return rec, err
		}
		n, err := strconv.Atoi(strings.TrimSpace(string(out)))
		if err != nil {
			return rec, fmt.Errorf("read replicas of %s: %q", key, out)
		}
		rec = WorkloadRecord{Namespace: p.Namespace, Workload: p.Workload, OriginalReplicas: n, CurrentReplicas: n}
	}
	want := p.Replicas
	if want == RestoreReplicas {
		want = rec.OriginalReplicas
	}
	if want < 0 {
		return rec, fmt.Errorf("invalid replicas %d", p.Replicas)
	}
	// Record before acting.
	if _, err := t.State.Update(func(s *State) error {
		if _, ok := s.Workloads[key]; !ok {
			s.Workloads[key] = rec
		}
		return nil
	}); err != nil {
		return rec, err
	}
	if _, err := t.kubectl(ctx, "scale", p.Workload, "-n", p.Namespace, fmt.Sprintf("--replicas=%d", want)); err != nil {
		return rec, err
	}
	st, err = t.State.Update(func(s *State) error {
		r := s.Workloads[key]
		r.CurrentReplicas, r.ChangedAt = want, time.Now().UTC()
		if want == r.OriginalReplicas {
			delete(s.Workloads, key) // back to original: nothing left to roll back
		} else {
			s.Workloads[key] = r
		}
		return nil
	})
	if err != nil {
		return rec, err
	}
	rec.CurrentReplicas = want
	return rec, nil
}
